import numpy as np
from PIL import Image,ImageDraw
from scipy import ndimage as ndi
from scipy.sparse import csr_matrix
from scipy.sparse.csgraph import dijkstra
M=np.array(Image.open('/app/target.png'))[:,:,0]<100
L,N=ndi.label(M)
D=ndi.distance_transform_edt(M)
MM=.00022186

def contours(mask):
 # Oriented pixel-square edges; ink on the right.
 edges={}
 y,x=np.where(mask)
 for yy,xx in zip(y,x):
  if yy==0 or not mask[yy-1,xx]:edges.setdefault((xx,yy),[]).append((xx+1,yy))
  if xx==mask.shape[1]-1 or not mask[yy,xx+1]:edges.setdefault((xx+1,yy),[]).append((xx+1,yy+1))
  if yy==mask.shape[0]-1 or not mask[yy+1,xx]:edges.setdefault((xx+1,yy+1),[]).append((xx,yy+1))
  if xx==0 or not mask[yy,xx-1]:edges.setdefault((xx,yy+1),[]).append((xx,yy))
 loops=[]
 while edges:
  start=next(iter(edges));p=start;ls=[]
  while True:
   ls.append(p);q=edges[p].pop()
   if not edges[p]:del edges[p]
   p=q
   if p==start:break
  if len(ls)>5:
   a=np.array(ls,dtype=float)-.5
   a=ndi.gaussian_filter1d(a,1.2,axis=0,mode='wrap')
   loops.append(a)
 return loops

def resample(a, step=.65,closed=False):
 if closed:a=np.vstack([a,a[0]])
 ds=np.linalg.norm(np.diff(a,axis=0),axis=1);s=np.r_[0,np.cumsum(ds)]
 si=np.linspace(0,s[-1],max(2,int(np.ceil(s[-1]/step))+1))
 return np.stack([np.interp(si,s,a[:,k]) for k in range(a.shape[1])],axis=1)

def getloops(comp):
 mask=L==comp; loops=[]
 for level in np.arange(1.0,D[mask].max(),2.4):
  for a in contours(mask & (D>level)):
   if len(a)>5:loops.append((level,a))
 return loops

def path_for(comp):
 loops=getloops(comp)
 # Start with innermost, ends on outer contour. Every point carries depth.
 loops.sort(key=lambda l:-l[0])
 result=[]; previous=None
 # Safe transfer routes within original ink using sparse shortest paths.
 mask=L==comp; yy,xx=np.where(mask); ids=np.full(mask.shape,-1,int);ids[yy,xx]=np.arange(len(xx))
 er=[];ec=[];ew=[]
 for dy,dx in [(0,1),(1,0),(1,1),(1,-1)]:
  y2=yy+dy;x2=xx+dx;ok=(y2>=0)&(y2<1024)&(x2>=0)&(x2<1024);idx=np.where(ok)[0];j=ids[y2[ok],x2[ok]];k=j>=0;idx=idx[k];j=j[k]
  w=np.hypot(dx,dy)*(1+2/np.maximum(D[yy[idx],xx[idx]],.5))
  er.extend(idx);ec.extend(j);ew.extend(w);er.extend(j);ec.extend(idx);ew.extend(w)
 graph=csr_matrix((ew,(er,ec)),shape=(len(xx),len(xx)))
 def route(a,b):
  ia=ids[int(round(a[1])),int(round(a[0]))];ib=ids[int(round(b[1])),int(round(b[0]))]
  if ia<0 or ib<0:raise ValueError(('outside',a,b))
  ds,pred=dijkstra(graph,directed=False,indices=ia,return_predecessors=True)
  chain=[ib]
  while chain[-1]!=ia:chain.append(pred[chain[-1]])
  return np.stack([xx[chain[::-1]],yy[chain[::-1]]],axis=1).astype(float)
 for level,a in loops:
  if previous is not None:
   k=np.argmin(np.linalg.norm(a-previous,axis=1));a=np.roll(a,-k,axis=0)
   # lower pressure without breaking paper contact
   result += [[*previous,.00022]]*8
   rt=resample(route(previous,a[0]),step=1.0)
   result += [[*p,.00022] for p in rt]
  a=resample(a,step=.65,closed=True)
  # Pressure ramp whilst moving; extra pass over the opening portion.
  extra=min(len(a)-1,25)
  aa=np.vstack([a,a[1:extra+1]])
  dep=np.full(len(aa),.0011)
  dep[:15]=np.linspace(.00022,.0011,15)
  dep[-10:]=np.linspace(.0011,.00022,10)
  result += [[*p,d] for p,d in zip(aa,dep)]
  previous=aa[-1]
 return np.array(result)

if __name__=='__main__':
 for c in range(1,N+1):
  p=path_for(c);np.save('/app/output/path%d.npy'%c,p);print(c,len(getloops(c)),len(p))
